from typing import Optional
from taf.ul.sc.enb.airscale import AirScale  # type: ignore
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.devices.bts.coam import COAM
from taf.ul.sc.perf.devices.bts.ems import Ems
from taf.ul.sc.syslog import Syslog  # type: ignore
from taf.ul.sc.perf.devices.bts.enb.generic_enb import GenericEnb
from taf.ul.sc.perf.devices.bts.airscale_functionality import AirScaleFunctionality


class AirScaleEnb(AirScaleFunctionality, GenericEnb):

    def __init__(self,
                 bts: AirScale,
                 workstation: Optional[UnixFunctionality] = None,
                 api: Optional[COAM] = None,
                 ems: Optional[Ems] = None,
                 syslog: Optional[Syslog] = None,
                 ):

        super(AirScaleEnb, self).__init__(bts=bts,
                                          workstation=workstation,
                                          api=api,
                                          ems=ems,
                                          syslog=syslog
                                          )

    dsp_script = "collect_dsp_stats_FSMr3.py"
